details.uiProgram:
root = Workspace({navigation: "tabs", views: [scope_by_repository, open_gaps_by_type, changes_by_repository, alert_audit_rows, batch_summary], inputs: [
    {
      fields: ["alerts", "assessments"],
      id: "batch_source",
      inputPort: "batch",
      title: "本批告警与范围判断材料"
    }
  ]})

scope_by_repository = Groups({
  columns: [
    {field: "repository", label: "仓库"},
    {field: "requestedRef", label: "分支/版本"},
    {field: "baseline", label: "扫描基线"},
    {field: "cve", label: "告警漏洞"},
    {field: "alertCount", label: "告警条数"},
    {field: "conclusion", label: "判断"},
    {field: "disposition", label: "处置"},
    {field: "status", label: "闭环状态"},
    {field: "successor", label: "修复后版本"}
  ],
  groupBy: "repository",
  output: "scope",
  rowKey: "relationId",
  title: "受影响范围与版本（按仓库）",
  detail: scope_by_repository_detail,
  actions: [Input({
    execute: true,
    fields: ["observedBaseline", "conclusion", "reason", "evidence"],
    id: "supplement_check",
    label: "补充核查材料",
    recordField: "record",
    selection: "one",
    when: {field: "status", message: "仅未匹配判断的范围需要补核查材料", operator: "equals", value: "待补判断或证据"},
    method: Method("补充核查材料并重新汇总 · 09d16f9d", "records")
  })]
})

open_gaps_by_type = Groups({
  columns: [
    {field: "alertId", label: "告警ID"},
    {field: "relationId", label: "调查范围"},
    {field: "repository", label: "仓库"},
    {field: "requestedRef", label: "分支"},
    {field: "cve", label: "漏洞"},
    {field: "conclusion", label: "判断"},
    {field: "disposition", label: "处置"},
    {field: "gapType", label: "缺口类型"},
    {field: "nextAction", label: "下一步"}
  ],
  groupBy: "gapType",
  output: "openGaps",
  rowKey: "alertId",
  title: "待处理缺口（按类型）",
  detail: open_gaps_by_type_detail,
  actions: [Input({
    execute: true,
    fields: ["confirm", "confirmationNote"],
    id: "confirm_exception",
    label: "确认例外并重新汇总",
    recordField: "record",
    selection: "one",
    when: {field: "gapType", message: "该告警为未确认例外，需要用户明确确认后才能重新汇总", operator: "equals", value: "例外待用户确认"},
    method: Method("记录人工例外决定并重新汇总 · fe849f88", "records")
  })]
})

changes_by_repository = List({
  columns: [
    {field: "repository", label: "实施仓库"},
    {field: "requestedRef", label: "分支"},
    {field: "changeCount", label: "改动数"},
    {field: "changeIds", label: "改动"},
    {field: "coveredCves", label: "覆盖漏洞"},
    {field: "coveredRelationCount", label: "覆盖范围数"}
  ],
  output: "repoChanges",
  rowKey: "key",
  title: "实施仓库与改动",
  detail: changes_by_repository_detail
})

alert_audit_rows = List({
  columns: [
    {field: "id", label: "告警ID"},
    {field: "relationId", label: "调查范围"},
    {field: "repository", label: "仓库"},
    {field: "requestedRef", label: "分支"},
    {field: "cve", label: "漏洞"},
    {field: "conclusion", label: "判断"},
    {field: "disposition", label: "处置"},
    {field: "accepted", label: "已闭环"}
  ],
  output: "alertAudit",
  rowKey: "id",
  title: "逐条告警核对",
  detail: alert_audit_rows_detail
})

batch_summary = Report({
  output: "batchSummary",
  title: "批次核对摘要",
  detail: batch_summary_detail,
  actions: [Review({
    id: "submit_review",
    label: "提交人工验收核对",
    selection: "none",
    when: {field: "unresolvedAlerts", message: "仍有未闭环告警：请先补齐核查材料或确认例外，再进入人工验收", operator: "equals", value: 0}
  })]
})

scope_by_repository_detail = Detail({
  title: "受影响范围与版本（按仓库）详情",
  fields: [
    {field: "alertIds", label: "覆盖的告警ID"},
    {field: "changeIds", label: "关联改动"},
    {field: "evidence", label: "影响判断依据"},
    {field: "verificationEvidence", label: "修复验证依据"},
    {field: "reason", label: "判断说明"},
    {field: "confirmation", label: "用户确认记录"}
  ]
})

open_gaps_by_type_detail = Detail({
  title: "待处理缺口（按类型）详情",
  fields: [
    {field: "reason", label: "说明"},
    {field: "evidence", label: "现有依据"},
    {field: "confirmation", label: "确认记录"}
  ]
})

changes_by_repository_detail = Detail({
  title: "实施仓库与改动详情",
  fields: [
    {field: "changes", label: "改动明细（含依赖与覆盖范围）"}
  ]
})

alert_audit_rows_detail = Detail({
  title: "逐条告警核对详情",
  fields: [
    {field: "reason", label: "说明"},
    {field: "evidence", label: "影响依据"},
    {field: "confirmation", label: "确认记录"}
  ]
})

batch_summary_detail = Detail({
  title: "批次核对摘要详情",
  fields: [
    {field: "totalAlerts", label: "告警总数"},
    {field: "acceptedAlerts", label: "已闭环（修复或有证据排除/例外已确认）"},
    {field: "unresolvedAlerts", label: "未闭环"},
    {field: "fixedAlerts", label: "按修复处理"},
    {field: "excludedAlerts", label: "按证据排除"},
    {field: "exceptionAlerts", label: "按例外处理"},
    {field: "exceptionAwaitingUser", label: "例外待用户确认"},
    {field: "missingAssessmentAlerts", label: "缺判断材料"},
    {field: "notice", label: "说明"}
  ]
})

